# ---------------------------------------------------------------------------
# Extraction helpers
# ---------------------------------------------------------------------------

def parse_post(md_path):
    """Read a markdown file and split title / subtitle / body."""
    text = md_path.read_text()

    # Strip the leading H1 from the body so it's not rendered twice.
    h1_match = re.match(r"^#\s+(.+?)\n", text)
    if not h1_match:
        raise ValueError(f"{md_path.name}: no H1 found")
    title = h1_match.group(1).strip()
    body = text[h1_match.end():]

    # The subtitle is the next non-blank line if it's an italic line ("*...*").
    subtitle = ""
    sub_match = re.match(r"\s*\*([^*\n]+?)\*\s*\n", body)
    if sub_match:
        subtitle = sub_match.group(1).strip()
        body = body[sub_match.end():]

    # Skip a leading horizontal rule (most posts start with "---\n" after subtitle).
    body = re.sub(r"^\s*---\s*\n", "", body, count=1)

    return title, subtitle, body


def to_html(md_body):
    """Render markdown to HTML.

    After conversion, demote any <h1> tags to <h2> since the post template
    already provides the page-level <h1> for the title.  This prevents
    'Multiple H1' SEO warnings when markdown source uses # headings.
    """
    html = markdown.markdown(
        md_body,
        extensions=[
            FencedCodeExtension(),
            TableExtension(),
            SaneListExtension(),
            TocExtension(toc_depth="2-3", marker=""),
            "smarty",
        ],
        output_format="html5",
    )
    # Demote h1 → h2 in rendered content (template already has the page h1)
    html = re.sub(r'<h1\b', '<h2', html)
    html = re.sub(r'</h1>', '</h2>', html)
    # Give every <table> an accessible name (a11y/table-duplicate-name)
    html = _caption_tables(html)
    # Add aria-label to bare <table> tags for accessibility
    html = re.sub(r'<table>(?!\s*<caption)', '<table aria-label="Data table">', html)
    return html


def _caption_tables(html):
    """Add a screen-reader caption to each <table> that lacks one.

    Markdown tables render without a <caption>, so assistive tech has no way to
    tell one table from another on a table-heavy page (e.g. the glossary). Derive
    an accessible name from the nearest preceding <h2>/<h3> and inject it as a
    visually-hidden <caption>. Tables already carrying a caption are left alone.
    """
    token = re.compile(r'<h([23])\b[^>]*>(.*?)</h\1>|<table\b[^>]*>', re.S)
    out, pos, last_heading = [], 0, None
    for m in token.finditer(html):
        out.append(html[pos:m.start()])
        chunk = m.group(0)
        if chunk.startswith('<table'):
            follows = html[m.end():m.end() + 30]
            if '<caption' not in follows and last_heading:
                name = re.sub(r'<[^>]+>', '', last_heading).strip().replace('"', '&quot;')
                if name:
                    chunk += f'<caption class="sr-only">{name}</caption>'
        else:
            last_heading = m.group(2)
        out.append(chunk)
        pos = m.end()
    out.append(html[pos:])
    return ''.join(out)


